#!/usr/bin/env python3
"""Build the parameter table in docs/parameters.md from nextflow_schema.json.

    .github/scripts/param_table.py --write    rewrite the table
    .github/scripts/param_table.py --check    exit 1 if it is out of date

The schema is the one place a parameter is described, and --help already reads
it. The table used to be maintained by hand next to a note admitting it would
drift. CI runs --check, so now it cannot.

Only the text between the two markers is touched. Everything else in
docs/parameters.md is written by a person.
"""

import argparse
import difflib
import json
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
SCHEMA = ROOT / "nextflow_schema.json"
PAGE = ROOT / "docs" / "parameters.md"

START = "<!-- generated by .github/scripts/param_table.py, do not edit by hand -->"
END = "<!-- end generated -->"

# schema type plus format, as something a reader recognises on the command line
TYPES = {
    "file-path": "file",
    "directory-path": "directory",
    "path": "path",
}


def render_type(spec):
    fmt = spec.get("format")
    if fmt in TYPES:
        return TYPES[fmt]
    return {"boolean": "flag", "integer": "integer", "number": "number"}.get(
        spec.get("type"), "string"
    )


def render_default(spec):
    if "default" not in spec:
        return "none"
    value = spec["default"]
    if isinstance(value, bool):
        return "`true`" if value else "`false`"
    if value == "":
        return "none"
    return f"`{value}`"


def cell(text):
    return text.replace("|", "\\|").strip()


def build():
    schema = json.loads(SCHEMA.read_text())
    groups = schema.get("$defs") or schema["definitions"]

    out = [START, ""]
    for group in groups.values():
        out.append(f"### {group.get('title', 'Other')}")
        out.append("")
        if group.get("description"):
            out.append(cell(group["description"]))
            out.append("")
        out.append("| Parameter | Type | Default | Description |")
        out.append("|---|---|---|---|")
        for name, spec in group["properties"].items():
            out.append(
                f"| `--{name}` | {render_type(spec)} | {render_default(spec)} "
                f"| {cell(spec.get('description', ''))} |"
            )
        out.append("")
    out.append(END)
    return "\n".join(out)


def splice(page_text, table):
    before, _, rest = page_text.partition(START)
    if not rest:
        sys.exit(f"{PAGE} has no {START} marker")
    _, _, after = rest.partition(END)
    return before + table + after


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--write", action="store_true")
    ap.add_argument("--check", action="store_true")
    args = ap.parse_args()
    if not (args.write or args.check):
        ap.error("pass --write or --check")

    current = PAGE.read_text()
    updated = splice(current, build())

    if args.write:
        if updated != current:
            PAGE.write_text(updated)
            print(f"rewrote {PAGE.relative_to(ROOT)}")
        else:
            print("already up to date")
        return

    if updated != current:
        diff = difflib.unified_diff(
            current.splitlines(True),
            updated.splitlines(True),
            "docs/parameters.md",
            "generated from nextflow_schema.json",
        )
        sys.stdout.writelines(diff)
        sys.exit(
            "\ndocs/parameters.md is out of date. "
            "Run .github/scripts/param_table.py --write"
        )
    print("docs/parameters.md matches nextflow_schema.json")


if __name__ == "__main__":
    main()
